import{_ as e,o as a,c as t,a4 as _}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知2026-07-02","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知2026-07-02","date":"2026-07-02T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://www.moa.gov.cn/govpublic/SCYJJXXS/202607/t20260702_6485474.htm","summary":"高级检索\\n索 引  号\\n07B050403202600105\\n信息所属单位\\n市场与信息化司\\n信息名称\\n农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知\\n文　　号\\n农办市[2026]6号\\n生效日期\\n2026年06月26日\\n发布日期\\n2026年07月02日\\n内容概述\\n2026年9月23日(农历秋分),将迎来第九个中国农民丰收节(以下简称“丰收节”)。...\\n","contentHash":"eaa4da8cfd0e8c0c0d3d16cbd6ebbde9","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-07-02-农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知.md","filePath":"policies/2026-07-02-农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知.md"}'),n={name:"policies/2026-07-02-农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知.md"};function o(r,p,s,l,c,i){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知2026-07-02" tabindex="-1">农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知2026-07-02 <a class="header-anchor" href="#农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知2026-07-02" aria-label="Permalink to &quot;农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知2026-07-02&quot;">​</a></h1><blockquote><p>来源: <a href="https://www.moa.gov.cn/govpublic/SCYJJXXS/202607/t20260702_6485474.htm" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-07-02 摘要: 高级检索 索 引 号 07B050403202600105 信息所属单位 市场与信息化司 信息名称 农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知 文　　号 农办市[2026]6号 生效日期 2026年06月26日 发布日期 2026年07月02日 内容概述 2026年9月23日(农历秋分),将迎来第九个中国农民丰收节(以下简称“丰收节”)。...</p></blockquote><p>高级检索</p><h2 id="农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知" tabindex="-1">农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知 <a class="header-anchor" href="#农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知" aria-label="Permalink to &quot;农业农村部办公厅关于做好2026年中国农民丰收节有关工作的通知&quot;">​</a></h2><p>发布时间：2026年07月02日</p><p>字体：[大 中 小]</p><p>2026年9月23日(农历秋分),将迎来第九个中国农民丰收节(以下简称“丰收节”)。习近平总书记连续8年向全国广大农民和工作在“三农”战线上的同志们致以节日祝贺和诚挚问候,对扎实推进乡村全面振兴寄予期盼重托。为深入贯彻习近平总书记关于“三农”工作的重要论述和重要指示精神,按照党中央、国务院决策部署,切实办好今年丰收节,营造城乡共庆丰收的浓厚氛围。现将有关事项通知如下。</p><p>一、总体要求</p><p>坚持以习近平新时代中国特色社会主义思想为指导,深入贯彻党的二十大和二十届历次全会精神,全面贯彻习近平总书记关于“三农”工作的重要论述和重要指示精神,锚定农业农村现代化,以扎实推进乡村全面振兴为总抓手,以学习运用“千万工程”经验为引领,秉承“庆祝丰收、弘扬文化、振兴乡村”的宗旨,以“丰收开新局 实干促振兴”为主题,坚持农民主体、农业主线、农村主场,精心组织、广泛动员、下沉基层,务实开展形式多样、丰富多彩的为农服务和庆祝活动,全面展示新时代新征程“三农”发展成就,宣传党的强农惠农富农政策,弘扬优秀农耕文化,提振促进城乡消费,做强丰收文化、丰收经济和丰收品牌,努力将丰收节打造成展示“三农”向好的重要平台、促进城乡消费的重要载体、弘扬农耕文化的重要阵地。</p><p>二、突出农民主体,城乡共庆丰收佳节</p><p>(一)展示丰收成果,凝聚推进农业农村现代化奋斗力量。全面展示“三农”发展取得的辉煌成就,持续巩固拓展脱贫攻坚成果,推进宜居宜业和美乡村建设成效,展现乡村振兴和农业丰收成果。聚焦统筹发展科技农业、绿色农业、质量农业、品牌农业,结合农民群众生产生活实际需求,因地制宜展示农业科技创新成果,推出一批人工智能、智慧农业等应用场景,推广一批绿色高效种养技术,推介一批农业精品品牌和优质特色农产品,引领带动广大农民群众守牢国家粮食安全底线,提高乡村产业发展水平,提升农业综合生产能力和质量效益。</p><p>(二)做好为农服务,提升农民荣誉感获得感。依托丰收节系列庆祝活动,集中发布惠农政策举措,组织开展义诊、普法宣传、科技下乡、走访慰问等服务,做好第四次全国农业普查宣传推广工作,办成一批农民群众可感可及的实事好事。深入挖掘宣传扎根生产一线、守护粮食安全的基层典型,保护和调动农民务农种粮积极性。推介新型农业经营主体率先提单产和各地完善农业经营体系、支撑主导产业发展的经验做法,推介乡村产业带头人和乡村治理人才,讲好助农丰收增收故事,激励各类人才下乡服务和创业就业,汇聚扎实推进乡村全面振兴的强大力量。</p><p>(三)弘扬农耕文化,培育文明乡风。因地制宜举办专题展示、成果发布、文化体验等活动,加强农耕文化弘扬传承。推动优质文化资源直达乡村,丰富农村文化产品和服务供给,广泛动员乡土文化能人、乡村工匠、非遗代表性传承人、文化产业特派员等,组织开展民俗文化、民间艺术、非遗展演等活动。办好群众性文化体育活动,不断满足农民群众对精神文化生活的新需求新期待。依托农村戏台、文化广场、文化礼堂及新时代文明实践所(站)等乡村文化阵地,开展美德传承、家风培育、文明宣讲、榜样宣传等活动,推动形成向上向善的乡村道德风尚。用好古村落、古镇、古建筑以及名人故居、传统街区等,植入丰收主题元素,营造浓厚的庆丰收氛围。</p><p>(四)提振城乡消费,促进农民丰收增收。多部门联合办好丰收节“金秋消费季”,遵循节庆经济发展规律,充分挖掘市场需求和潜力,组织开展品牌推介、产销对接、乡村美食推广等形式多样的促消费活动。务实创新办好丰收市集,结合各地产业特色,精心策划主题,严格把控产品质量与商户准入门槛,创新打造“可玩、可购、可参与”的沉浸式消费场景,推荐一批乡村休闲旅游精品线路,推动农特产品展销、民俗文化展示、乡村旅游体验深度融合,将丰收市集办成有吸引力的“消费IP”。联合金融机构、电商平台等市场主体,强化流量赋能、信贷支持、消费补贴等措施,多措并举提振城乡消费。</p><p>(五)做强丰收品牌,推动节日成风化俗。加强丰收节节庆品牌打造,不断提升节日影响力、带动力和生命力。建立丰收地图,全面展示推广各地“丰”字号活动,推介丰收美景、农事体验、文化活动和特色农产品。培育品牌活动,支持打造丰收集、丰收课、丰收游、丰收村等系列特色品牌。构建传播矩阵,统筹线上线下传播渠道,联动主流媒体与社交平台,广泛发动县级融媒体中心,加强丰收节宣传推广,讲好中国丰收故事,持续提升节日带动效应,让丰收节真正成为扎根乡土、惠及全民的标志性节庆品牌。</p><p>三、统筹谋划,扎实有序做好丰收节筹办工作</p><p>(一)强化组织推动。各地要将办好丰收节作为重要政治任务,进一步提高政治站位,精心谋划组织,广泛动员参与,推动工作重心进一步向县、乡、村下沉,引导社会各界共庆共祝丰收。组委会统筹谋划年度主题主线,做好对各地筹办工作指导,高质量办好湖北襄阳全国主场活动。实施丰收节庆祝活动清单管理,发布年度重点活动计划,控制活动总量,提升活动质效,推动常态化监测监督。各级农业农村部门要统筹谋划、协同联动,主动对接相关部门,坚持农民主体,深入调研需求,提早谋划制定工作方案。农业农村部各司局单位、省级农业农村部门于7月28日前将本单位工作方案报送农业农村部市场与信息化司审核。</p><p>(二)严格规范管理。严格贯彻落实中央八项规定及其实施细则精神,树立和践行正确政绩观,坚决执行党中央、国务院关于规范节庆展会论坛等活动和整治形式主义为基层减负的决策部署,不折不扣落实中央关于过紧日子要求,坚持简朴务实办节导向,反对形式主义,力戒奢靡之风。按照“谁举办谁负责,谁组织谁负责”的原则,依法依规履行活动审批程序,未经批准不得违规嵌套开展展会、论坛、赛事、评奖、创建示范、达标以及授牌命名“城市”、“之乡”、“基地”等活动,不得违规或者随意冠以“国家”、“中国”、“中华”、“全国”、“亚洲”、“世界”等名称,严禁借节日之名行不相关之事,不得借举办活动违规收费。强化活动全流程管理,用好现有场地和设施,能用尽用、能留尽留,严禁违规用地、大拆大建、铺张浪费。严守财经纪律,严防廉政风险和财务风险。</p><p>(三)加强安全管理。牢固树立安全生产红线意识和底线思维,健全完善安全生产管理机制,完善突发事件应急预案,压紧压实各相关单位责任,确保各项安全措施落细落实。活动举办地要强化场地安全管控,规范人员密集场所秩序管理,做好人流疏导和应急准备。严格把控食品安全,加强农产品质量安全监管。健全信息监测机制,及时回应社会关切,确保丰收节活动安全、平稳、有序开展。</p><p>(四)做好总结推广。省级农业农村部门要系统总结丰收节举办经验和成效,及时准确掌握本地区今年丰收节活动数量、规模、内容和效果,以及丰收市集举办情况和成效,并推荐3—5个典型案例,与本年度丰收节总结一并于10月15日前报送至农业农村部市场与信息化司。</p><p>联系人:陈晨 白玲</p><p>联系电话:010-59191724/1598,59192101(传真)</p><p>电子邮箱:scsscjsc@agri.gov.cn</p><p>附件:2026年中国农民丰收节重点活动计划</p><p>农业农村部办公厅</p><p>2026年6月26日</p><p>附件：</p><ul><li>附件：2026年中国农民丰收节重点活动计划.docx</li></ul><p>相关新闻：</p><p>扫一扫在手机打开当前页</p><p><a href="https://www.moa.gov.cn/govpublic/SCYJJXXS/202607/t20260702_6485474.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',31)])])}const h=e(n,[["render",o]]);export{f as __pageData,h as default};
